const product = $input.first().json;

const currentStock = parseFloat(product.Current_Stock) || 0;
const maxStock = parseFloat(product.Max_Stock) || 100;
const thresholdPct = parseFloat(product.Reorder_Threshold_Pct) || 20;

// Calculate stock percentage
const stockPct = maxStock > 0 ? (currentStock / maxStock) * 100 : 0;
const stockPctRounded = Math.round(stockPct * 100) / 100;

// Determine if reorder needed
const needsReorder = stockPct <= thresholdPct;

// Determine urgency level
let urgencyLevel;
let urgencyEmoji;
if (stockPct <= 5) {
  urgencyLevel = 'CRITICAL';
  urgencyEmoji = '🔴';
} else if (stockPct <= 10) {
  urgencyLevel = 'HIGH';
  urgencyEmoji = '🟠';
} else if (stockPct <= thresholdPct) {
  urgencyLevel = 'LOW';
  urgencyEmoji = '🟡';
} else {
  urgencyLevel = 'OK';
  urgencyEmoji = '🟢';
}

// Calculate reorder quantity
const reorderQty = parseFloat(product.Reorder_Qty) || Math.round(maxStock * 0.5);

// Calculate estimated cost
const unitPrice = parseFloat(product.Unit_Price) || 0;
const estimatedCost = (reorderQty * unitPrice).toFixed(2);

return [{
  json: {
    ...product,
    Stock_Pct       : stockPctRounded,
    Needs_Reorder   : needsReorder,
    Urgency_Level   : urgencyLevel,
    Urgency_Emoji   : urgencyEmoji,
    Reorder_Qty     : reorderQty,
    Estimated_Cost  : estimatedCost,
    Checked_At      : new Date().toISOString().split('T')[0]
  }
}];
